<?php
// Isolated, in-memory accounting tests; never modifies the WordPress database.
if ( PHP_SAPI !== 'cli' ) exit;
ob_start(); require __DIR__ . '/project-workflow.php'; ob_end_clean();
$_SERVER['REQUEST_METHOD'] = 'POST';
$spare = document_workflow( 0, $project );
$saved_meta = $meta[$spare]; $saved_project = $meta[$project]; $saved_payment = $meta[$payment];
$number = co_sales_meta( $spare, 'number' );
expect_workflow( '' === co_sales_quote_delete_reason( $spare ), 'unused quote can be deleted' );
action_workflow( 'admin_post_co_sales_quote_lifecycle', array( 'document_id' => $spare, 'operation' => 'trash' ) );
expect_workflow( 'trash' === get_post_status( $spare ), 'quote moved into Trash' );
expect_workflow( ! in_array( $spare, array_column( co_sales_documents(), 'ID' ), true ), 'Trash absent from active lists' );
expect_workflow( $saved_project === $meta[$project] && $saved_payment === $meta[$payment], 'project and payment untouched' );
