co_sales_quote_lifecycle( $spare );
expect_workflow( 'trash' === get_post_status( $spare ), 'repeat delete is idempotent' );
expect_workflow( co_sales_next_number( 'quotation', $client, co_sales_meta( $spare, 'issue_date' ) ) !== $number, 'trashed number stays reserved' );
