rejected_workflow( fn() => co_project_derive_document( $spare, 1 ), 'cannot invoice a deleted quote' );
$_GET = array( 'document' => $spare );
rejected_workflow( fn() => co_sales_edit_page(), 'cannot open trashed quote for editing' );
rejected_workflow( fn() => co_sales_preview_page(), 'cannot preview trashed quote' );
$_GET = array( 'type' => 'quotation', 'view' => 'trash' );
ob_start(); co_sales_documents_page(); $trash_html = ob_get_clean();
expect_workflow( str_contains( $trash_html, $number ) && str_contains( $trash_html, 'กู้คืน' ), 'Trash view has quote and restore action' );
action_workflow( 'admin_post_co_sales_quote_lifecycle', array( 'document_id' => $spare, 'operation' => 'restore' ) );
co_sales_quote_lifecycle( $spare, true );
expect_workflow( 'publish' === get_post_status( $spare ) && $number === co_sales_meta( $spare, 'number' ), 'restore and retry preserve document identity' );
expect_workflow( $saved_project === $meta[$project], 'restore does not select an agreement' );
// A signed QO with invoices, receipts and paid installments deletes as one set.
